<div class="page-heading"><div><p class="eyebrow">ADMINISTRATOR · PEOPLE</p><h1>Caretaker review.</h1><p class="page-lead">Review applications before a caretaker becomes eligible for assignments.</p></div><span class="date-chip"><?= icon('shield', 'size-4') ?> <?= count($caretakers) ?> application<?= count($caretakers) === 1 ? '' : 's' ?></span></div>
<div class="review-intro" role="note"><?= icon('shield', 'size-5') ?><span>Verify identity, contact details, and cemetery permission outside this pilot interface before approving an application.</span></div>
<?php if (!$caretakers): ?><section class="surface-card empty-state"><div class="next-illustration" aria-hidden="true"><?= icon('users', 'size-10') ?></div><h2>No applications yet</h2><p>When a caretaker applies, their details will appear here for review.</p></section><?php else: ?><div class="review-list"><?php foreach ($caretakers as $caretaker): ?><article class="surface-card review-card"><div class="review-card-top"><div><p class="eyebrow">CARETAKER APPLICATION</p><h2><?= e($caretaker['full_name']) ?></h2><p><?= e($caretaker['email']) ?> · <?= e($caretaker['phone'] ?? 'No number') ?></p></div><?= status_badge(ucfirst($caretaker['status']), $caretaker['status'] === 'verified' ? 'success' : ($caretaker['status'] === 'pending' ? 'warning' : 'neutral')) ?></div><dl class="review-details"><div><dt>Service area</dt><dd><?= e($caretaker['service_area']) ?></dd></div><div><dt>Applied</dt><dd><?= e(date('M j, Y', strtotime($caretaker['created_at']))) ?></dd></div><?php if ($caretaker['experience']): ?><div class="review-wide"><dt>Experience</dt><dd><?= nl2br(e($caretaker['experience'])) ?></dd></div><?php endif; ?><?php if ($caretaker['review_note']): ?><div class="review-wide"><dt>Last review note</dt><dd><?= nl2br(e($caretaker['review_note'])) ?></dd></div><?php endif; ?></dl>
    <?php if (in_array($caretaker['status'], ['pending', 'verified', 'rejected', 'suspended'], true)): ?><form method="post" action="?page=caretakers" class="review-form"><?= csrf_field() ?><input type="hidden" name="action" value="review_caretaker"><input type="hidden" name="subject_id" value="<?= (int) $caretaker['id'] ?>"><div class="form-field"><label for="review-note-<?= (int) $caretaker['id'] ?>">Review note <span class="optional-label">Required for rejection or suspension</span></label><textarea id="review-note-<?= (int) $caretaker['id'] ?>" class="textarea textarea-bordered w-full" name="note" rows="2" maxlength="500" placeholder="Explain your decision when needed."></textarea></div><div class="review-actions"><?php if ($caretaker['status'] === 'pending'): ?><button class="btn btn-primary btn-sm" name="decision" value="verify" type="submit">Verify caretaker</button><button class="btn btn-outline btn-sm" name="decision" value="reject" type="submit">Reject application</button><?php elseif ($caretaker['status'] === 'verified'): ?><button class="btn btn-outline btn-sm" name="decision" value="suspend" type="submit">Suspend caretaker</button><?php elseif ($caretaker['status'] === 'suspended'): ?><button class="btn btn-primary btn-sm" name="decision" value="restore" type="submit">Restore verification</button><?php elseif ($caretaker['status'] === 'rejected'): ?><button class="btn btn-primary btn-sm" name="decision" value="verify" type="submit">Verify after review</button><?php endif; ?></div></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
<section class="surface-card authorization-panel" aria-labelledby="authorization-title"><div class="card-heading"><div><p class="eyebrow">CEMETERY ACCESS</p><h2 id="authorization-title">Where caretakers may work</h2></div></div><p class="admin-form-intro">Verification confirms the person. Cemetery authorization separately records where they may receive future assignments. Access pauses while a caretaker or cemetery is inactive.</p>
    <?php if (!$caretakers): ?><div class="admin-empty"><p>Applications will appear here after a caretaker signs up.</p></div><?php else: ?><div class="authorization-list"><?php foreach ($caretakers as $caretaker): ?><?php $grants = $accessByCaretaker[(int) $caretaker['id']] ?? []; ?><div class="authorization-row"><div class="authorization-person"><strong><?= e($caretaker['full_name']) ?></strong><?= status_badge(ucfirst($caretaker['status']), $caretaker['status'] === 'verified' ? 'success' : 'neutral') ?></div><div class="authorization-grants"><?php if (!$grants): ?><span class="muted-paragraph">No cemetery authorization</span><?php else: ?><?php foreach ($grants as $grant): ?><form method="post" action="?page=caretakers" class="grant-pill"><?= csrf_field() ?><input type="hidden" name="action" value="change_caretaker_access"><input type="hidden" name="decision" value="revoke"><input type="hidden" name="caretaker_id" value="<?= (int) $caretaker['id'] ?>"><input type="hidden" name="cemetery_id" value="<?= (int) $grant['cemetery_id'] ?>"><span><?= e($grant['cemetery_name']) ?></span><button type="submit" aria-label="Remove <?= e($caretaker['full_name']) ?> from <?= e($grant['cemetery_name']) ?>">Remove</button></form><?php endforeach; ?><?php endif; ?></div><?php if ($caretaker['status'] === 'verified'): ?><form method="post" action="?page=caretakers" class="grant-form"><?= csrf_field() ?><input type="hidden" name="action" value="change_caretaker_access"><input type="hidden" name="decision" value="grant"><input type="hidden" name="caretaker_id" value="<?= (int) $caretaker['id'] ?>"><label class="sr-only" for="grant-cemetery-<?= (int) $caretaker['id'] ?>">Cemetery for <?= e($caretaker['full_name']) ?></label><select class="select select-bordered select-sm" name="cemetery_id" id="grant-cemetery-<?= (int) $caretaker['id'] ?>" required><option value="">Choose cemetery</option><?php foreach ($cemeteries as $cemetery): ?><?php if ($cemetery['status'] === 'active' && !in_array((int) $cemetery['id'], array_map(static fn ($grant) => (int) $grant['cemetery_id'], $grants), true)): ?><option value="<?= (int) $cemetery['id'] ?>"><?= e($cemetery['name']) ?></option><?php endif; ?><?php endforeach; ?></select><button class="btn btn-primary btn-sm" type="submit">Authorize</button></form><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?>
</section>
